        if (r.gas && r.gas.room) out.rows.push([T('گرادیان A–a', 'A–a gradient'), fa(r.gas.aa, 0) + ' mmHg']);
        if (r.gas && !r.gas.room) out.rows.push(['PaO₂/FiO₂', fa(r.gas.pf, 0)]);
